import{s as t}from"./index-j8XKRsNn.js";var a={getActiveLogo:async()=>{try{return(await t.get("/logo/active")).data}catch(a){throw a}},getAllLogos:async(a=10)=>{try{return(await t.get("/logos",{params:{per_page:a}})).data}catch(o){throw o}},uploadLogo:async a=>{try{const o=new FormData;return o.append("logo",a),(await t.post("/logo",o,{headers:{"Content-Type":"multipart/form-data"}})).data}catch(o){throw o}},activateLogo:async a=>{try{return(await t.patch(`/logo/${a}/activate`)).data}catch(o){throw o}},deleteLogo:async a=>{try{return(await t.delete(`/logo/${a}`)).data}catch(o){throw o}}};export{a as t};